const D = { energy:.62, offset:.32, alpha:.8, density:.5, tint:.58, delay:.5, speed:1, scale:1, hue:28, x:.5, y:.5, style:'latent', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,v)=>{h=((h%360)+360)%360;s/=100;v/=100;const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r,g,b;const sg=Math.floor(h/60)%6;if(sg===0){r=c;g=x;b=0;}else if(sg===1){r=x;g=c;b=0;}else if(sg===2){r=0;g=c;b=x;}else if(sg===3){r=0;g=x;b=c;}else if(sg===4){r=x;g=0;b=c;}else{r=c;g=0;b=x;}return [((r+m)*255)|0,((g+m)*255)|0,((b+m)*255)|0];};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width,H=height,u=Math.min(W,H),t=K.t,key=W+'x'+H,dc=drawingContext;

// ---- ring of past frames + a half-res staging plate
if(!S.ring||S.key!==key){
  let rw,rh;
  if(W>=H){ rw=320; rh=Math.max(24,Math.round(320*H/W)); } else { rh=320; rw=Math.max(24,Math.round(320*W/H)); }
  if(S.ring) for(const q of S.ring) if(q&&q.remove) q.remove();
  if(S.tmp&&S.tmp.remove) S.tmp.remove();
  S.ring=[]; S.ringEl=[];
  for(let i=0;i<3;i++){ const q=createGraphics(rw,rh); q.pixelDensity(1); S.ring.push(q); S.ringEl.push(q.elt||q.canvas); }
  S.tmp=createGraphics(Math.max(64,Math.round(W*0.5)), Math.max(36,Math.round(H*0.5)));
  S.tmp.pixelDensity(1); S.tmpEl=S.tmp.elt||S.tmp.canvas;
  S.wr=0; S.tick=0; S.filled=0; S.key=key;
}
const tmp=S.tmp, tg=tmp.drawingContext, tw=tmp.width, th=tmp.height, uu=Math.min(tw,th);

const en=clp(P.energy,0,1);
const sp=0.45+clp(P.speed,.15,4)*0.55;
const style=P.style, hue=((P.hue%360)+360)%360, alpha=clp(P.alpha,0,1);

// ---- capture the scene BEFORE we lay anything down; ghosts never re-enter the ring
S.tick=(S.tick|0)+1;
const stride=Math.max(2,Math.round(3+clp(P.delay,0,1)*24));
if(S.filled<3 || (S.tick%stride)===0){
  const wq=S.ring[S.wr];
  wq.clear(); wq.drawingContext.drawImage(dc.canvas,0,0,wq.width,wq.height);
  S.wr=(S.wr+1)%3; if(S.filled<3) S.filled++;
}

// ---- act: multi-minute programs
let ofsMul=1, gMul=1, mottMul=1;
if(P.act==='wind'){ ofsMul = 0.55+0.85*(0.5+0.5*Math.sin(t*0.017*sp)); mottMul=1.25; }
else if(P.act==='expose'){ gMul = 0.72+0.5*K.swell+0.35*K.intensity+0.25*A.rms; }

let nG, tA, gBase, ofsScale, mottBase;
if(style==='multiple'){      nG=2+Math.round(clp(P.density,0,1)*1); tA=clp(P.tint,0,1)*0.5; gBase=0.46; ofsScale=1.9; mottBase=0.62; }
else if(style==='solarize'){ nG=1+Math.round(clp(P.density,0,1));   tA=clp(P.tint,0,1)*0.4; gBase=0.55; ofsScale=1.2; mottBase=0.72; }
else if(style==='bleed'){    nG=1+Math.round(clp(P.density,0,1));   tA=clp(P.tint,0,1)*1.15; gBase=0.40; ofsScale=0.7; mottBase=1.0; }
else {                       nG=1+Math.round(clp(P.density,0,1)*2); tA=clp(P.tint,0,1); gBase=0.46; ofsScale=1.0; mottBase=1.0; }
nG=Math.max(1,Math.min(3,nG));
tA=clp(tA,0,1);
const ofs=clp(P.offset,0,1)*ofsScale;
const gA=clp(alpha*(0.25+0.75*en)*gBase*gMul, 0, 0.85);

// ---- lay the delayed ghosts down on the staging plate (additive, as light on film is)
tmp.clear();
tg.globalCompositeOperation='lighter';
for(let k=0;k<nG;k++){
  const src=S.ringEl[(((S.wr-1-k)%3)+3)%3];
  const ph=k*2.1+fr(k*7+1)*6.2832;
  const orb=t*0.021*sp*(k%2?-1:1)+ph;
  const dx=ofs*uu*(0.42*Math.sin(t*0.053*sp+ph)+0.26*Math.sin(t*0.131*sp+ph*1.7)+0.30*Math.cos(orb))*ofsMul;
  const dy=ofs*uu*(0.38*Math.cos(t*0.061*sp+ph*1.3)+0.22*Math.sin(t*0.113*sp+ph*0.9)+0.28*Math.sin(orb))*ofsMul;
  const rot=ofs*(0.030*Math.sin(t*0.037*sp+ph)+0.016*Math.sin(t*0.097*sp+ph*2.2));
  const scl=1+ofs*(0.05+0.035*Math.sin(t*0.071*sp+ph*1.1))+(style==='bleed'?0.09:0);
  tg.globalAlpha=Math.pow(0.62,k);
  tg.save();
  tg.translate(tw*0.5+dx+(P.x-0.5)*tw*0.12, th*0.5+dy+(P.y-0.5)*th*0.12);
  tg.rotate(rot); tg.scale(scl,scl);
  tg.drawImage(src,-tw*0.5,-th*0.5,tw,th);
  tg.restore();
}
tg.globalAlpha=1;

// ---- the transfer is a stain, not a copy: tint the ghost where it exists.
// This is also what makes the pass legible over a dark scene, where a plain
// additive ghost of a dark frame would add nothing at all and read STATIC.
if(tA>0.004){
  const tc=hsb2rgb(hue,style==='solarize'?38:62,style==='bleed'?76:88);
  tg.globalCompositeOperation='source-atop';
  tg.fillStyle=`rgba(${tc[0]},${tc[1]},${tc[2]},${tA.toFixed(4)})`;
  tg.fillRect(0,0,tw,th);
}

// ---- uneven pressure: carve drifting soft holes so the bleed-through is mottled.
// These translate continuously and wrap -> a motion floor no 8s window can cancel.
{
  const nm=5+Math.round(clp(P.density,0,1)*6);
  const mott=clp((0.45+0.55*en)*mottBase*mottMul,0,0.98);
  tg.globalCompositeOperation='destination-out';
  for(let i=0;i<nm;i++){
    const rr=tw*(0.15+0.20*fr(i*3.7+2))*Math.max(0.35,P.scale);
    const vx=(0.032+0.038*fr(i*5+3))*(fr(i*13)<0.5?-1:1)*sp;
    const vy=(0.014+0.022*fr(i*9+4))*(fr(i*17)<0.5?-1:1)*sp;
    const mx=((((fr(i*11+5)+t*vx)%1)+1)%1)*(tw+2*rr)-rr;
    const my=((((fr(i*19+6)+t*vy)%1)+1)%1)*(th+2*rr)-rr;
    const ma=clp((0.55+0.45*fr(i*23+7))*mott,0,1);
    const rg=tg.createRadialGradient(mx,my,0,mx,my,rr);
    rg.addColorStop(0,`rgba(0,0,0,${ma.toFixed(4)})`);
    rg.addColorStop(0.6,`rgba(0,0,0,${(ma*0.45).toFixed(4)})`);
    rg.addColorStop(1,'rgba(0,0,0,0)');
    tg.fillStyle=rg; tg.fillRect(mx-rr,my-rr,rr*2,rr*2);
  }
  tg.globalCompositeOperation='source-over';
}

// ---- print it through
dc.globalCompositeOperation = style==='solarize' ? 'exclusion' : 'lighter';
dc.globalAlpha=gA;
dc.drawImage(S.tmpEl,0,0,W,H);
dc.globalAlpha=1; dc.globalCompositeOperation='source-over';
blendMode(BLEND); dc.shadowBlur=0; noStroke();
